import time
import threading


def debounce(wait: float):
    """Decorator: call fn at most once per `wait` seconds of quiet."""
    def decorator(fn):
        timer = None
        def wrapped(*args, **kwargs):
            nonlocal timer
            def call():
                fn(*args, **kwargs)
            if timer is not None:
                timer.cancel()
            timer = threading.Timer(wait, call)
            timer.start()
        return wrapped
    return decorator


@debounce(0.3)
def on_type(text):
    print('searched:', text)

# Call rapidly; on_type runs once, 0.3s after the last call.

