// Leading edge (run immediately, then wait):
function debounceLeading(fn, wait = 300) {
    let timer, lastRan;
    return function (...args) {
        const now = Date.now();
        if (lastRan && now - lastRan < wait) {
            clearTimeout(timer);
            timer = setTimeout(() => {
                lastRan = Date.now();
                fn.apply(this, args);
            }, wait - (now - lastRan));
            return;
        }
        lastRan = now;
        fn.apply(this, args);
    };
}

