import time
import threading


def throttle(interval: float):
    """Decorator: run fn at most once per `interval` seconds."""
    def decorator(fn):
        last_run = 0.0
        lock = threading.Lock()
        def wrapped(*args, **kwargs):
            nonlocal last_run
            with lock:
                now = time.monotonic()
                if now - last_run < interval:
                    return
                last_run = now
            return fn(*args, **kwargs)
        return wrapped
    return decorator


@throttle(1.0)
def on_scroll():
    print('scrolled')

# Called 100 times in a second, on_scroll runs ~once.

