function throttle(fn, limit = 1000) {
    let lastRun = 0;
    return function (...args) {
        const now = Date.now();
        if (now - lastRun >= limit) {
            lastRun = now;
            fn.apply(this, args);
        }
    };
}

// Trailing edge (guarantee the final call runs):
function throttleTrailing(fn, limit = 1000) {
    let lastRun = 0, timer;
    return function (...args) {
        const now = Date.now();
        const remaining = limit - (now - lastRun);
        if (remaining <= 0) {
            clearTimeout(timer);
            lastRun = now;
            fn.apply(this, args);
        } else if (!timer) {
            timer = setTimeout(() => {
                lastRun = Date.now();
                timer = null;
                fn.apply(this, args);
            }, remaining);
        }
    };
}

