# Python's @property is the equivalent:
import math

class Circle:
    def __init__(self, radius):
        self.radius = radius

    @property
    def area(self):
        return math.pi * self.radius ** 2

    @property
    def diameter(self):
        return self.radius * 2

    @diameter.setter
    def diameter(self, d):
        self.radius = d / 2

c = Circle(5)
print(c.area)     # 78.5...
c.diameter = 20
print(c.radius)   # 10

